import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const n="/assets/image%20(128).Bw8OD-2w.png",s="/assets/image%20(129).DafyVZF5.png",i="/assets/image%20(130).BDu5uQxu.png",l="/assets/image%20(131).DUouuNTe.png",d="/assets/image%20(132).tFwAhZrr.png",y=JSON.parse('{"title":"Dhan","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/dhan.md","filePath":"connect-brokers/brokers/dhan.md"}'),c={name:"connect-brokers/brokers/dhan.md"};function h(p,t,g,u,m,f){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="dhan" tabindex="-1">Dhan <a class="header-anchor" href="#dhan" aria-label="Permalink to &quot;Dhan&quot;">​</a></h1><p>Dhan is a new-generation financial services platform that empowers traders and investors to build, automate, and execute their trading strategies. Through <strong>DhanHQ APIs</strong>, users can connect their Dhan account with tools like <strong>Tradeboard</strong> and create their own trading automation setup that is fully self-hosted and secure.</p><hr><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Dhan provides two main types of APIs:</p><table tabindex="0"><thead><tr><th>API Type</th><th>Features</th><th>Cost</th></tr></thead><tbody><tr><td><strong>Trading APIs</strong></td><td>Order Placement, Position Management, Portfolio &amp; Funds, Order Postbacks, Statement Reports</td><td><strong>Free of Cost</strong></td></tr><tr><td><strong>Data APIs</strong></td><td>Real-time Prices, Historical Data (5 years), 20-Level Market Depth, Option Chain APIs, Expired Options Data</td><td>₹499/month or ₹399/month (₹4,788/year)</td></tr></tbody></table><hr><h3 id="steps-for-integration" tabindex="-1">Steps for Integration <a class="header-anchor" href="#steps-for-integration" aria-label="Permalink to &quot;Steps for Integration&quot;">​</a></h3><h4 id="step-1-log-in-to-dhan-web-portal" tabindex="-1"><strong>Step 1: Log in to Dhan Web Portal</strong> <a class="header-anchor" href="#step-1-log-in-to-dhan-web-portal" aria-label="Permalink to &quot;**Step 1: Log in to Dhan Web Portal**&quot;">​</a></h4><p>Visit <a href="https://web.dhan.co/" target="_blank" rel="noreferrer">web.dhan.co</a> and sign in to your Dhan account.</p><hr><h4 id="step-2-access-dhanhq-apis" tabindex="-1"><strong>Step 2: Access DhanHQ APIs</strong> <a class="header-anchor" href="#step-2-access-dhanhq-apis" aria-label="Permalink to &quot;**Step 2: Access DhanHQ APIs**&quot;">​</a></h4><p>Click on your profile icon at the top-right and select <strong>“Access DhanHQ APIs”</strong>.</p><p>From this page, you can:</p><ul><li>Generate API Keys</li><li>Enable TOTP</li><li>Setup Static IP</li><li>Manage Trading &amp; Data APIs</li></ul><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><hr><h4 id="step-3-switch-to-api-key-mode" tabindex="-1"><strong>Step 3: Switch to API Key Mode</strong> <a class="header-anchor" href="#step-3-switch-to-api-key-mode" aria-label="Permalink to &quot;**Step 3: Switch to API Key Mode**&quot;">​</a></h4><p>By default, DhanHQ opens in <strong>Access Token</strong> mode.<br> Use the toggle on the top-right to switch to <strong>API Key Mode</strong>.</p><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><hr><h4 id="step-4-generate-a-new-api-key" tabindex="-1"><strong>Step 4: Generate a New API Key</strong> <a class="header-anchor" href="#step-4-generate-a-new-api-key" aria-label="Permalink to &quot;**Step 4: Generate a New API Key**&quot;">​</a></h4><ol><li>Under <strong>Generate new API Key</strong>, enter: <ul><li><strong>Application Name</strong>: e.g. <code>tradeboard</code></li><li><strong>Redirect URL</strong>: <code>http://127.0.0.1:5000/dhan/callback</code></li><li>(Optional) <strong>Postback URL</strong> if your system supports order postbacks</li></ul></li><li>Click <strong>Generate API Key</strong>.</li><li>Copy your: <ul><li><strong>API Key</strong></li><li><strong>API Secret</strong></li></ul></li></ol><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><hr><h4 id="step-5-retrieve-client-id" tabindex="-1"><strong>Step 5: Retrieve Client ID</strong> <a class="header-anchor" href="#step-5-retrieve-client-id" aria-label="Permalink to &quot;**Step 5: Retrieve Client ID**&quot;">​</a></h4><ol><li>From the same profile menu, select <strong>“My Profile on Dhan.”</strong></li><li>Scroll to <strong>Profile Details</strong> and copy your <strong>Client ID</strong>.<br> This will be used as part of your API credentials.</li></ol><figure><img src="'+l+'" alt=""><figcaption></figcaption></figure><hr><h4 id="step-6-enable-totp-mandatory" tabindex="-1"><strong>Step 6: Enable TOTP (Mandatory)</strong> <a class="header-anchor" href="#step-6-enable-totp-mandatory" aria-label="Permalink to &quot;**Step 6: Enable TOTP (Mandatory)**&quot;">​</a></h4><ul><li>Under <strong>Optional Settings - down below the API Key section</strong>, click <strong>Set-up TOTP.</strong></li><li>Follow the instructions to configure two-factor authentication for API access.</li><li>This is <strong>mandatory</strong> for all Dhan API users.</li></ul><hr><h4 id="step-7-setup-static-ip-optional-mandatory-from-jan-2026" tabindex="-1"><strong>Step 7: Setup Static IP (Optional / Mandatory from Jan 2026)</strong> <a class="header-anchor" href="#step-7-setup-static-ip-optional-mandatory-from-jan-2026" aria-label="Permalink to &quot;**Step 7: Setup Static IP (Optional / Mandatory from Jan 2026)**&quot;">​</a></h4><ul><li>Click <strong>Static IP Setting</strong> under Optional Settings.</li><li>Add up to two IP addresses (e.g., your server or office IP).</li><li>You can update these every 7 days.</li><li>From <strong>January 2026</strong>, setting at least one <strong>Static IP</strong> will become mandatory.</li></ul><figure><img src="'+d+`" alt=""><figcaption></figcaption></figure><hr><h3 id="environment-configuration" tabindex="-1">Environment Configuration <a class="header-anchor" href="#environment-configuration" aria-label="Permalink to &quot;Environment Configuration&quot;">​</a></h3><p>Once your credentials are generated, configure them in your <code>.env</code> file:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_dhan_clientid:::your_dhan_apikey&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_dhan_apisecret&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/dhan/callback&#39;</span></span></code></pre></div><hr><h3 id="api-costs-summary" tabindex="-1">API Costs Summary <a class="header-anchor" href="#api-costs-summary" aria-label="Permalink to &quot;API Costs Summary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API Type</th><th>Description</th><th>Cost</th></tr></thead><tbody><tr><td><strong>Trading APIs</strong></td><td>Order, Position, Portfolio, Funds &amp; Report APIs</td><td><strong>Free of Cost</strong></td></tr><tr><td><strong>Data APIs</strong></td><td>Real-time + Historical Data (5 years), Market Depth, Option Chain</td><td>₹499/month (or ₹399/month billed yearly)</td></tr></tbody></table><hr><h3 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><ul><li>Keep your <strong>API Key, Secret, and Client ID private</strong>.</li><li>Do not share credentials with third-party applications.</li><li>Always enable <strong>TOTP</strong> for added security.</li><li>Use <strong>Static IPs</strong> when deploying in production environments.</li><li><strong>Daily login to Tradeboard Portal is mandatory.</strong></li></ul><hr><p>Integrating with <strong>DhanHQ APIs</strong> unlocks the ability to automate strategies, execute trades, and analyze data directly within your own infrastructure.<br> When used with <strong>Tradeboard</strong>, you can self-host and run your entire algo trading stack, with full control and zero vendor lock-in.</p><hr><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/dhan/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>BCD</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,51)])])}const P=e(c,[["render",h]]);export{y as __pageData,P as default};
